package com.medtrack.inventory.dto; import com.medtrack.inventory.entity.*; import java.time.Instant; import java.util.*; public record JournalEntryDetailResponse(UUID id,String entryNumber,String entryType,String referenceEntityType,UUID referenceEntityId,String description,Instant createdAt,List<Line> lines){public record Line(UUID id,UUID batchId,String accountType,UUID warehouseId,String direction,int quantity,Integer availableBefore,Integer availableDelta,Integer availableAfter,Integer reservedBefore,Integer reservedDelta,Integer reservedAfter,Integer quarantinedBefore,Integer quarantinedDelta,Integer quarantinedAfter,Integer balanceAfter){} public static JournalEntryDetailResponse of(InventoryJournalEntry e){return new JournalEntryDetailResponse(e.getId(),e.getEntryNumber(),e.getEntryType().name(),e.getReferenceEntityType(),e.getReferenceEntityId(),e.getDescription(),e.getCreatedAt(),e.getLines().stream().map(l->new Line(l.getId(),l.getBatch().getId(),l.getAccountType().name(),l.getWarehouse()==null?null:l.getWarehouse().getId(),l.getDirection().name(),l.getQuantity(),l.getAvailableBefore(),l.getAvailableDelta(),l.getAvailableAfter(),l.getReservedBefore(),l.getReservedDelta(),l.getReservedAfter(),l.getQuarantinedBefore(),l.getQuarantinedDelta(),l.getQuarantinedAfter(),l.getBalanceAfter())).toList());}}
